import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"歸妹","description":"焦氏易林注 - 歸妹","frontmatter":{"title":"歸妹","description":"焦氏易林注 - 歸妹"},"headers":[],"relativePath":"zh/classics/jiaoyilin/054.md","filePath":"zh/classics/jiaoyilin/054.md"}'),l={name:"zh/classics/jiaoyilin/054.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="歸妹" tabindex="-1">歸妹 <a class="header-anchor" href="#歸妹" aria-label="Permalink to “歸妹”">​</a></h1><h3 id="歸妹-1" tabindex="-1">歸妹 <a class="header-anchor" href="#歸妹-1" aria-label="Permalink to “歸妹”">​</a></h3><h3 id="歸妹之乾" tabindex="-1">歸妹之乾 <a class="header-anchor" href="#歸妹之乾" aria-label="Permalink to “歸妹之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>荊木冬生，司寇緩刑。威權在下，國亂且傾。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此仍用遇卦象。歸妹上震為荊木、為生，坎為冬，故曰冬生。坎為寇、為刑，震生，故曰緩刑。伏艮為國，離為亂，故曰國亂且傾。</p><h3 id="歸妹之坤" tabindex="-1">歸妹之坤 <a class="header-anchor" href="#歸妹之坤" aria-label="Permalink to “歸妹之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>喘牛傷暑，不能耕畝。草萊不闢，年歲無有。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>世說：滿奮曰，臣猶吳牛見月而喘。蓋吳牛畏暑，見月以為日，故喘也。又《漢書丙吉傳》見牛喘吐舌而問之。此用遇卦《歸妹》象。離為牛，震聲，故曰喘牛。離為夏，故曰傷暑。震為草萊、為年歲，坎折，兌毀，故無有。○耕，宋元本作成，依汲古。</p><h3 id="歸妹之屯" tabindex="-1">歸妹之屯 <a class="header-anchor" href="#歸妹之屯" aria-label="Permalink to “歸妹之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>魚欲負流，眾不同心。至德潛伏。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坤為魚，艮為負，坎為流，坤上艮，艮上坎，故曰魚欲負流。坤為眾，坎為心，震起，艮止，故不同心。震為德，坎隱，故曰潛伏。○潛伏，宋元本作安樂，依汲古。</p><h3 id="歸妹之蒙" tabindex="-1">歸妹之蒙 <a class="header-anchor" href="#歸妹之蒙" aria-label="Permalink to “歸妹之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>春耕有息，秋入利福。獻豜私豵，以樂成功。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>互震為春、為耕、為生，故曰有息。伏兌為秋，伏巽為入、為利，震為福，故曰秋入利福。《詩豳風》言私其豵，獻豜於公，《傳》豕一歲曰豵，三歲曰豜。坎為豕，艮手為獻，艮為小，坎隱，故曰私豵。震為樂、為功，艮為成。○豵，汲古作豭，依宋元本。</p><h3 id="歸妹之需" tabindex="-1">歸妹之需 <a class="header-anchor" href="#歸妹之需" aria-label="Permalink to “歸妹之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>生有聖德，上配太極。皇靈建中，授我以福。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《需》。</p><h3 id="歸妹之訟" tabindex="-1">歸妹之訟 <a class="header-anchor" href="#歸妹之訟" aria-label="Permalink to “歸妹之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>右撫琴頭，左手援帶。凶訟不已，相與爭戾，失利而歸。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>此似用《歸妹》象。兌為右，坎為首，震為樂，故曰右撫琴頭。震為左，伏艮為手、為援，巽為帶，故曰左手援帶。兌口，震言，故曰訟、曰爭。巽為利，坎失，故曰失利。</p><h3 id="歸妹之師" tabindex="-1">歸妹之師 <a class="header-anchor" href="#歸妹之師" aria-label="Permalink to “歸妹之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>炙魚棝鬥，張伺夜鼠。舌不忍味，機發為祟，笮不得去。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《井》之《坎》。棝，依校，宋元本作枯，汲古作拈。卦旁通《同人》。巽為魚，下離，故曰炙魚。坤為閉，故曰棝鬥。震為鬥也。張、夜，汲古作陰、作碩，忍作思，機作譏，均依宋元本。《說文》棝鬥可以射鼠。</p><h3 id="歸妹之比" tabindex="-1">歸妹之比 <a class="header-anchor" href="#歸妹之比" aria-label="Permalink to “歸妹之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>申酉脫服，牛馬休息。君子以安，勞者得歡。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坤位申，坎位酉。服，猶駕也。坤為牛，坎為馬，艮止，故脫服而休息也。艮為君子、為安，坎為勞，五統群陰，故曰得歡。</p><h3 id="歸妹之小畜" tabindex="-1">歸妹之小畜 <a class="header-anchor" href="#歸妹之小畜" aria-label="Permalink to “歸妹之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>堯問尹壽，聖德增益。使民不疲，安無怵惕。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《遯》之《隨》。尹壽，人名，《新序》堯學乎尹壽。壽，汲古作爵，非。</p><h3 id="歸妹之履" tabindex="-1">歸妹之履 <a class="header-anchor" href="#歸妹之履" aria-label="Permalink to “歸妹之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>孤公憂婦，獨宿悲苦。目張耳鳴，莫與笑語。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《歸妹》。巽為寡，乾父，故曰孤公。</p><h3 id="歸妹之泰" tabindex="-1">歸妹之泰 <a class="header-anchor" href="#歸妹之泰" aria-label="Permalink to “歸妹之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>外得好畜，相與嫁娶。仁賢集聚，咨詢厥事。傾奪我城，使家不寧。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為養、為畜，在上，故曰外得好畜。震為嫁、為娶、為仁賢、為言，故曰咨詢。坤為集聚，艮為城、為家，三五艮覆，故曰傾城、曰家不寧。按：上六城復於隍，即謂三至上艮覆也。</p><h3 id="歸妹之否" tabindex="-1">歸妹之否 <a class="header-anchor" href="#歸妹之否" aria-label="Permalink to “歸妹之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>煎砂盛暑，鮮有不朽。去河千里，敗我利市。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>老牛盲馬，去之何悔。艮為砂、為火，故曰煎砂。候卦乾在己，巽後天亦居己，艮火，故曰盛暑。巽為朽、為利市，坤為河、為千里、為我、為敗、為老牛，乾為馬，坤迷，故曰盲馬。○千，元本、汲古、丁本作三，依宋本。牛盲，汲古訛手育，依宋元本。</p><h3 id="歸妹之同人" tabindex="-1">歸妹之同人 <a class="header-anchor" href="#歸妹之同人" aria-label="Permalink to “歸妹之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>甲乙戊庚，隨時轉行。不失常節，萌芽律屈。咸達出生，各樂其類。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>詳《漸》之《旅》。</p><h3 id="歸妹之大有" tabindex="-1">歸妹之大有 <a class="header-anchor" href="#歸妹之大有" aria-label="Permalink to “歸妹之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>衣宵夜游，與君相遭。解除煩惑，使心不憂。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>乾為衣，《說文》衣，依也。伏坤為帛，故曰衣宵。宵綃同。《士昬禮》宵衣註宵讀為《詩》素衣朱綃之綃，綃，綺屬也。又《特牲饋食禮》主婦宵衣南面，鄭註：宵，綺屬也，此衣染之以黑，其繒本名曰宵。《詩》有素衣朱宵，《記》有玄宵衣，然則衣宵夜游者，即衣錦夜游也。伏坎為夜。乾為君，坎為心、為憂惑，坎伏，故解除。○衣，各本皆作依，依《小過》之《否》校。</p><h3 id="歸妹之謙" tabindex="-1">歸妹之謙 <a class="header-anchor" href="#歸妹之謙" aria-label="Permalink to “歸妹之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>死友絕朋，巧言為讒。覆白污玉，顏叔哀喑。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為朋友，坤為死，故曰死友絕朋。正反震，故曰巧言、曰讒。震為白、為玉，坤黑，故曰覆白污玉。艮為顏、為少子，故曰顏叔。坎為悲哀。顏叔未詳。</p><h3 id="歸妹之豫" tabindex="-1">歸妹之豫 <a class="header-anchor" href="#歸妹之豫" aria-label="Permalink to “歸妹之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>逐利三年，利走如神。展轉東西，如鳥避丸。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為逐，伏巽為利，坤為歲，震數三，故曰三年。震為神、為東，坎位西，為丸、為隱伏，艮為鳥，故曰如鳥避丸。</p><h3 id="歸妹之隨" tabindex="-1">歸妹之隨 <a class="header-anchor" href="#歸妹之隨" aria-label="Permalink to “歸妹之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>堤防壞決，河水泛溢。傷害禾稼，君孤獨宿。沒溺我邑。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為堤防，兌附決，故曰壞決。互大坎，故曰河水泛溢。震為禾稼，兌毀折，故曰傷害禾稼。震為君，坎為孤，坤為寡，故曰君孤獨宿。艮為邑。○泛溢，宋元本作放逸。稼下汲古多民流去室四字，宋元本無。君，宋元本作居，依汲古。</p><h3 id="歸妹之蠱" tabindex="-1">歸妹之蠱 <a class="header-anchor" href="#歸妹之蠱" aria-label="Permalink to “歸妹之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>陰陽隔塞，許嫁不答。旄丘新台，悔往嘆息。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>詳《晉》之《無妄》。旄，無妄作宛，宛丘，陳詩，旄丘，衛詩，姑兩存之。</p><h3 id="歸妹之臨" tabindex="-1">歸妹之臨 <a class="header-anchor" href="#歸妹之臨" aria-label="Permalink to “歸妹之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>伯夷叔齊，貞廉之師。以德防患，憂禍不存。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《乾》。</p><h3 id="歸妹之觀" tabindex="-1">歸妹之觀 <a class="header-anchor" href="#歸妹之觀" aria-label="Permalink to “歸妹之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>陽為狂悖，拔劍自傷，為身生殃。詳《明夷》之《井》。</p><h3 id="歸妹之噬嗑" tabindex="-1">歸妹之噬嗑 <a class="header-anchor" href="#歸妹之噬嗑" aria-label="Permalink to “歸妹之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>進士為官，不若服田，獲壽保年。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為官，震為士、為進，故曰進士。艮為田、為壽、為保，震為年。</p><h3 id="歸妹之賁" tabindex="-1">歸妹之賁 <a class="header-anchor" href="#歸妹之賁" aria-label="Permalink to “歸妹之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>耕石不生，棄禮無名。縫衣失針，襦褲不成。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為耕，上艮，故曰耕石。離為禮，艮為名，坎隱伏，故曰棄禮、曰無名。震為衣，坎為針，伏巽繩，故曰縫衣。坎失，故曰失針。震為襦，伏巽為褲，坎破，故不成。</p><h3 id="歸妹之剝" tabindex="-1">歸妹之剝 <a class="header-anchor" href="#歸妹之剝" aria-label="Permalink to “歸妹之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>靈龜陸處，一旦失所。伊子復耕，桀亂無輔。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮龜，處坤上，故曰陸處。</p><h3 id="歸妹之復" tabindex="-1">歸妹之復 <a class="header-anchor" href="#歸妹之復" aria-label="Permalink to “歸妹之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>室當源口，漂溺為海。財產殫盡，衣食無有。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤水，故曰漂溺。</p><h3 id="歸妹之無妄" tabindex="-1">歸妹之無妄 <a class="header-anchor" href="#歸妹之無妄" aria-label="Permalink to “歸妹之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>雞方啄粟，為狐所逐。走不得食，惶懼喘息。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>巽為雞，震為粟、為逐，艮為狐，乾惕，故曰惶懼。</p><h3 id="歸妹之大畜" tabindex="-1">歸妹之大畜 <a class="header-anchor" href="#歸妹之大畜" aria-label="Permalink to “歸妹之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>家在海隅，橈短流深。豈敢憚行，無木以趨。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《明夷》。橈短，依校，各本多作繞旋，繞，形訛，旋，音訛字。</p><h3 id="歸妹之頤" tabindex="-1">歸妹之頤 <a class="header-anchor" href="#歸妹之頤" aria-label="Permalink to “歸妹之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>他山之錯，與璆為仇。來攻吾城，傷我肌膚，國家騷憂。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為山、為錯，《禹貢》厥貢磬錯註：治玉之石曰錯，《詩小雅》他山之石，可以為錯。惟錯玉，故曰與璆為仇。璆，亦玉也。坤為仇、為城、為國、為傷，艮手為攻、為肌膚、為家，坤為憂也。○璆，宋元本作環，吾作我，均依汲古。</p><h3 id="歸妹之大過" tabindex="-1">歸妹之大過 <a class="header-anchor" href="#歸妹之大過" aria-label="Permalink to “歸妹之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>弊鏡無光，不見文章。少女不嫁，棄於其公。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>離為鏡，卦上下皆半離，故曰弊鏡。互大坎，故無光。坤為文章，坤伏，故曰不見文章。巽為少女，震為歸、為嫁、為公，震伏，故曰不嫁、曰棄於其公也。《易大過》以巽為少女，兌為老婦，故易林本之。</p><h3 id="歸妹之坎" tabindex="-1">歸妹之坎 <a class="header-anchor" href="#歸妹之坎" aria-label="Permalink to “歸妹之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>大蛇巨魚，相搏於郊。君臣隔塞，戴公廬漕。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《訟》。廬漕，依校，各本多作出廬，不協。第二句汲古作相輔殺之，第四句作郭公失廬。按：鄭有內蛇外蛇鬬之事，未有魚相搏者，據此林似為郭國將亡之事，而今不能考。</p><h3 id="歸妹之離" tabindex="-1">歸妹之離 <a class="header-anchor" href="#歸妹之離" aria-label="Permalink to “歸妹之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>絕世無嗣，福祿不存。精神渙散，離其躬身。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>艮為世，震為子，艮震皆伏，而兌為附決，故曰絕世無嗣、曰福祿不存。震又為福祿也。震為精神，互巽風，故曰渙散。艮為身，艮伏不見，故曰離。○不，元本作無，從宋本、汲古。</p><h3 id="歸妹之咸" tabindex="-1">歸妹之咸 <a class="header-anchor" href="#歸妹之咸" aria-label="Permalink to “歸妹之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>文德之君，養人致福。年無胎夭，國富民實。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>憂者之望，曾參盜息。通《損》。坤為文，震為德、為君、為人、為福，坤為養、為年歲，震為胎，坤為死、為夭，震福，故無。坤為國民、為富實。下二語有訛字，難解。○曾，宋本作憎，元本作增，姑從汲古，以俟再考。</p><h3 id="歸妹之恒" tabindex="-1">歸妹之恒 <a class="header-anchor" href="#歸妹之恒" aria-label="Permalink to “歸妹之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>合歡之國，喜為我福。東嶽南山，朝躋成恩。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《益》。坤為國，初至五正反震相對，故曰合歡之國。震為東，又為南，上艮，故曰東嶽南山。震為朝、為躋、為恩德。案：《周禮》視祲註雲：躋，虹也。《墉風》朝躋於西，崇朝其雨，疏亦訓躋為虹，言虹見於西方則雨氣應也。躋躋同字，然易林數見皆作躋，朝躋成恩者，言山嶽虹見雨應以成其恩澤也。○躋，汲古作濟，依宋元本。恩，宋元本作息，依汲古。恩與山韻。</p><h3 id="歸妹之遯" tabindex="-1">歸妹之遯 <a class="header-anchor" href="#歸妹之遯" aria-label="Permalink to “歸妹之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>憂人之患，履悖易顏。為身禍殘，率身自守。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>與喜相抱，長子成老，封受福祉。乾為畏惕，故曰憂患。伏震為履，坤為悖，艮為顏，坤為身、為禍。艮為守、為抱，震為喜、為長子，坤為老。後四句與前三句吉凶相反，定為衍文，本林至第三句而此。○老，汲古作考，義同。</p><h3 id="歸妹之大壯" tabindex="-1">歸妹之大壯 <a class="header-anchor" href="#歸妹之大壯" aria-label="Permalink to “歸妹之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>太公避紂，七十隱處。卒逢聖文，為王室輔。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>詳《明夷》之《坤》。逢，宋元本作受，依汲古。</p><h3 id="歸妹之晉" tabindex="-1">歸妹之晉 <a class="header-anchor" href="#歸妹之晉" aria-label="Permalink to “歸妹之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>江漢上流，政逆民憂。陰代其陽，雌為雄公。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>互坎為水，坤亦為水、為江漢、為流。坤為政、為民，逆行，故曰政逆民憂。坎為憂也。坤為陰、為雌，五陽位，陰居之，故曰代陽、曰雌為雄。○代，宋元本作伐，非，依汲古。</p><h3 id="歸妹之明夷" tabindex="-1">歸妹之明夷 <a class="header-anchor" href="#歸妹之明夷" aria-label="Permalink to “歸妹之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>縮緒亂絲，舉手為災。越畝逐兔，喪其衣褲。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>伏巽為緒、為絲，震為反，故曰縮緒。坤亂，故曰亂絲。坤為畝、為喪，震為兔、為越、為衣，伏巽為褲，坤喪，故曰喪其衣褲。○緒，汲古作縮，非，依宋元本。</p><h3 id="歸妹之家人" tabindex="-1">歸妹之家人 <a class="header-anchor" href="#歸妹之家人" aria-label="Permalink to “歸妹之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>臭彘腐木，與狼相輔。亡夫失子，憂及父母。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>巽為臭，坎豕，故曰臭彘。巽為木、為腐，狼象未詳。震為夫、為子，震伏，故曰亡失。坎為憂，巽為母，伏震為父。○木，宋元本作水，依汲古。</p><h3 id="歸妹之睽" tabindex="-1">歸妹之睽 <a class="header-anchor" href="#歸妹之睽" aria-label="Permalink to “歸妹之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>刲羊不當，女執空筐。兔跛鹿踦，緣山墜墮，讒佞亂作。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《歸妹》象。上二句歸妹上六意也。兌為羊，坎為刺，故曰刲羊。兌為女，震為筐，震虛，故曰女執空筐。震為兔、為鹿，互坎，故曰跛踦。伏艮為山，伏巽為墜墮，兌口震言，故曰讒佞亂作。</p><h3 id="歸妹之蹇" tabindex="-1">歸妹之蹇 <a class="header-anchor" href="#歸妹之蹇" aria-label="Permalink to “歸妹之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>拔劍傷手，見敵不喜。良臣無佐，困憂為咎。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>艮為劍、為手，坎為傷，故曰拔劍傷手。坎憂，上坎中爻坎，坎遇坎為敵，故曰見敵不喜。離為見，坎病，故不喜。艮為臣、為佐，坎為孤，故曰無佐。坎為困憂，《艮彖傳》雲上下敵應，即以艮見艮為敵也。○喜，宋元本作善，困作國，均依汲古。</p><h3 id="歸妹之解" tabindex="-1">歸妹之解 <a class="header-anchor" href="#歸妹之解" aria-label="Permalink to “歸妹之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>三羖五牂，相隨俱行。迷入空澤，循谷直北。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>徑涉六駁，為所傷賊。詳《無妄》之《觀》。賊，宋本、汲古作敗，依元本。徑皆作經，依汲古《無妄》之《觀》校。</p><h3 id="歸妹之損" tabindex="-1">歸妹之損 <a class="header-anchor" href="#歸妹之損" aria-label="Permalink to “歸妹之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>爭雞失羊，亡其金囊，利得不長。陳蔡之患，賴楚以安。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《恆》之《夬》。</p><h3 id="歸妹之益" tabindex="-1">歸妹之益 <a class="header-anchor" href="#歸妹之益" aria-label="Permalink to “歸妹之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>三驪負衡，南取芷香。秋蘭芬馥，盈滿神匱，利我仲季。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為馬，數三，故曰三驪。艮為負、為衡，巽為香、為蘭芷，震為南，故曰南取。伏兌為秋，故曰秋蘭。震為神、為匱，坤多，故曰盈滿。巽為利，艮為季。○衡，宋元本作銜，取芷作芷取，均依汲古。驪，汲古訛灑。</p><h3 id="歸妹之夬" tabindex="-1">歸妹之夬 <a class="header-anchor" href="#歸妹之夬" aria-label="Permalink to “歸妹之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>孟夏己醜，哀呼尼父。明德訖終，亂虐滋起。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《睽》之《恆》。夏，汲古作春，非。</p><h3 id="歸妹之姤" tabindex="-1">歸妹之姤 <a class="header-anchor" href="#歸妹之姤" aria-label="Permalink to “歸妹之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>履不容足，南山多葉。家有滎蘭，乃無病疾。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>震為履、為足，震伏，故不容足。乾為山、為南，巽為芝蘭，坤為疾病，坤伏，故無。○葉，宋本作草，元本作革。芝，宋元本作芳，均依汲古。</p><h3 id="歸妹之萃" tabindex="-1">歸妹之萃 <a class="header-anchor" href="#歸妹之萃" aria-label="Permalink to “歸妹之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>三足無頭，不知所之。心狂睛傷，莫使為明，不見日光。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>伏震，故曰三足。乾為頭，乾伏，故曰無頭。三至上正反震，故曰不知所之。坤為心，巽風，故曰心狂。兌為半離，易履卦謂之眇，故此曰睛傷。艮為日、為光，互巽為伏，故曰不見。○日，宋元本作月，非，依汲古。心狂睛傷，汲古作心在精傷，依宋元本。</p><h3 id="歸妹之升" tabindex="-1">歸妹之升 <a class="header-anchor" href="#歸妹之升" aria-label="Permalink to “歸妹之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>戴堯扶禹，松喬彭祖。西過王母，道路夷易，無敢難者。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《離》。松，汲古訛從，依宋元本。</p><h3 id="歸妹之困" tabindex="-1">歸妹之困 <a class="header-anchor" href="#歸妹之困" aria-label="Permalink to “歸妹之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>式微式微，憂禍相絆。隔以岩山，室家分散。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《謙》。絆，汲古作半，依宋元本。</p><h3 id="歸妹之井" tabindex="-1">歸妹之井 <a class="header-anchor" href="#歸妹之井" aria-label="Permalink to “歸妹之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>靈龜陸處，一旦失所。伊子復耕，桀亂無輔。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》林。</p><h3 id="歸妹之革" tabindex="-1">歸妹之革 <a class="header-anchor" href="#歸妹之革" aria-label="Permalink to “歸妹之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>仁德覆洽，恩及異域。澤被殊方，禍災隱伏。蠶不作室，寒無所得。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為恩德，坤為巽域、為殊方。兌為恩澤，坤為禍災，坎為隱伏，巽為蠶，坎為室，坎伏，故曰不作室。坎為寒室，繭也。</p><h3 id="歸妹之鼎" tabindex="-1">歸妹之鼎 <a class="header-anchor" href="#歸妹之鼎" aria-label="Permalink to “歸妹之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>夏麥，霜擊其芒。疾君敗國，使年夭傷。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《賁》。，汲古作，依宋元本。</p><h3 id="歸妹之震" tabindex="-1">歸妹之震 <a class="header-anchor" href="#歸妹之震" aria-label="Permalink to “歸妹之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>火雖熾，在吾後。寇雖多，在吾右。身安吉，不危殆。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《需》。</p><h3 id="歸妹之艮" tabindex="-1">歸妹之艮 <a class="header-anchor" href="#歸妹之艮" aria-label="Permalink to “歸妹之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>遼遠絕路，客宿多悔。頑囂相聚，生我畏惡。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《明夷》之《小畜》。遼遠，元本作遠遼，依宋本、汲古。</p><h3 id="歸妹之漸" tabindex="-1">歸妹之漸 <a class="header-anchor" href="#歸妹之漸" aria-label="Permalink to “歸妹之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>懸懸南海，去家萬里。飛兔腰褭，一日見母，除我憂悔。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《晉》之《坎》。腰褭，各本作褭駿，依《晉》之《坎》校。</p><h3 id="歸妹之歸妹" tabindex="-1">歸妹之歸妹 <a class="header-anchor" href="#歸妹之歸妹" aria-label="Permalink to “歸妹之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>堅冰黃鳥，常哀悲愁。不見白粒，但睹藜蒿。數驚鷙鳥，為我心憂。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《噬嗑》。○白，汲古作甘，睹作嘆，蒿作荊，依宋元本。鳥常，元本作裳鳥，似非。</p><h3 id="歸妹之豐" tabindex="-1">歸妹之豐 <a class="header-anchor" href="#歸妹之豐" aria-label="Permalink to “歸妹之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>困而後通，雖厄不窮。終得其願，姬薑相從。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為姬，巽為薑。</p><h3 id="歸妹之旅" tabindex="-1">歸妹之旅 <a class="header-anchor" href="#歸妹之旅" aria-label="Permalink to “歸妹之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>西賈巴蜀，寒雪至轂。欲前不還，得反空屋。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《解》。○空，元本作窒，依宋本。</p><h3 id="歸妹之巽" tabindex="-1">歸妹之巽 <a class="header-anchor" href="#歸妹之巽" aria-label="Permalink to “歸妹之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>新作初陵，爛陷難登。三駒摧車，躓頓傷頤。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>伏艮為陵，巽為爛，伏震為登，坎陷，故難登。震為駒，數三，坎破，故曰三駒摧車。伏坎為蹇，初至四互頤，故曰躓頓傷頤。</p><h3 id="歸妹之兌" tabindex="-1">歸妹之兌 <a class="header-anchor" href="#歸妹之兌" aria-label="Permalink to “歸妹之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>延頸望酒，不入我口。深目自苦，利得無有，幽人悅喜。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《無妄》之《大畜》。</p><h3 id="歸妹之渙" tabindex="-1">歸妹之渙 <a class="header-anchor" href="#歸妹之渙" aria-label="Permalink to “歸妹之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>仲春孟夏，和氣所舍。生我嘉福，國無殘賊。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>坎為仲，互震，故曰仲春。對卦離為夏，震為長，故曰孟夏。坎為和，震出，故曰舍。震為生、為嘉福，艮為國，坎為賊，風散，故無賊。舍，發也。</p><h3 id="歸妹之節" tabindex="-1">歸妹之節 <a class="header-anchor" href="#歸妹之節" aria-label="Permalink to “歸妹之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>張網捕鳩，兔離其災。雌雄俱得，為罝所賊。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>通《旅》。離為網、為鳩，艮為捕，震為兔，旅下卦震覆，故曰兔罹其災。離罹通用。艮為雄，互巽為雌，離罝在上，故曰雌雄俱得。巽為賊也。</p><h3 id="歸妹之中孚" tabindex="-1">歸妹之中孚 <a class="header-anchor" href="#歸妹之中孚" aria-label="Permalink to “歸妹之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>三人俱行，一人言北。伯仲欲南，少叔不得。中路分爭，道鬬相賊。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《巽》。爭道，汲古作道爭，依宋元本。</p><h3 id="歸妹之小過" tabindex="-1">歸妹之小過 <a class="header-anchor" href="#歸妹之小過" aria-label="Permalink to “歸妹之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>然諾不行，欺紿誤人。使我露宿，夜歸溫室。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>神怒不直，鬼擊其目。欲求福利，適反自賊。詳《恆》之《觀》。後三句宋元本作鬼欲求獨，刺擊其目，反言自賊，依汲古。</p><h3 id="歸妹之既濟" tabindex="-1">歸妹之既濟 <a class="header-anchor" href="#歸妹之既濟" aria-label="Permalink to “歸妹之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>陳辭達誠，使安不傾。增祿益壽，以成功名。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《明夷》之《晉》。</p><h3 id="歸妹之未濟" tabindex="-1">歸妹之未濟 <a class="header-anchor" href="#歸妹之未濟" aria-label="Permalink to “歸妹之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>火燒公床，破家滅亡。然得安昌，先憂重喪。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>半艮為床，重離，故曰燒。坎為破、為憂。</p>',320)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
